import {
    Table,
    ListColumn,
    GenericColumn,
    TranslatedTextColumn,
    IntegerColumn,
    ReferenceColumn,
    BooleanColumn,
    GuidColumn,
    UrlColumn,
} from '@servicenow/sdk/core'

export const topic = Table({
    actions: ['read', 'update', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        domain_master: 'taxonomy',
        synch_attachments: true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Topic',
    name: 'topic',
    schema: {
        not_available_for: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Not available for',
            maxLength: 1024,
            referenceTable: 'user_criteria',
        }),
        banner_image: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: 'Banner Image',
        }),
        topic_path: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Topic path',
            maxLength: 1024,
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        available_for: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Available for',
            maxLength: 1024,
            referenceTable: 'user_criteria',
        }),
        name: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Name',
            mandatory: true,
            maxLength: 60,
        }),
        icon: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: 'Icon',
        }),
        parent_topic: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Select a taxonomy and then choose a parent topic for this topic',
                    label: 'Parent topic',
                    plural: 'Parent topics',
                    language: 'en',
                },
            ],
            referenceTable: 'topic',
            referenceQual: 'javascript:new TopicList().childTopics(current.taxonomy,current.sys_id)',
        }),
        taxonomy: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Taxonomy',
            mandatory: true,
            referenceTable: 'taxonomy',
        }),
        topic_contributor: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Topic contributor',
            maxLength: 1024,
            referenceTable: 'user_criteria',
        }),
        apply_to_child_topics: BooleanColumn({
            default: false,
            label: 'Apply template to child topics',
        }),
        topic_based_navigation: BooleanColumn({
            default: false,
            label: 'Topic based navigation',
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 120,
        }),
        enable_user_criteria_check: BooleanColumn({
            default: false,
            label: 'Enable user criteria check',
        }),
        banner_image_url: UrlColumn({
            label: 'Banner Image URL',
        }),
        icon_url: UrlColumn({
            label: 'Icon URL',
        }),
        template: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Template',
            referenceTable: 'sp_page',
            referenceQual: 'category=sn_ex_sp_taxonomy^EQ',
        }),
        topic_manager: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Topic manager',
            maxLength: 1024,
            referenceTable: 'user_criteria',
        }),
    },
})
